<?php
require_once __DIR__.'/backend/authorization.php';require_once __DIR__.'/backend/db.php';require_once __DIR__.'/backend/csrf.php';requireRegularAdmin();
$id=(int)($_GET['id']??0);$stmt=$conn->prepare("SELECT b.*,GROUP_CONCAT(bi.service_id ORDER BY bi.id) service_ids,GROUP_CONCAT(bi.service_name ORDER BY bi.id SEPARATOR ', ') services FROM bookings b LEFT JOIN booking_items bi ON bi.booking_id=b.id WHERE b.id=? GROUP BY b.id");$stmt->bind_param('i',$id);$stmt->execute();$b=$stmt->get_result()->fetch_assoc();if(!$b||!in_array($b['status'],['Pending','Approved'],true))redirectTo('admin-bookings.php?error='.urlencode('Booking cannot be rescheduled.'));$days=(int)getSetting($conn,'booking_days_ahead','90');
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reschedule | Oh My Gracious</title><link rel="stylesheet" href="css/style.css"></head><body><header class="navbar"><div class="logo">Front Desk</div><nav><a href="admin-dashboard.php">Dashboard</a><a href="admin-bookings.php">Appointments</a><a href="availability-management.php">Availability</a><a href="customers.php">Customers</a><a href="staff-security.php">Security</a><a href="logout.php" class="logout-btn">Logout</a></nav></header><main class="page-wrap narrow"><div class="page-heading"><div><p class="eyebrow">RESCHEDULE</p><h1><?=h($b['full_name'])?></h1><p><?=h($b['services']?:$b['service_type'])?></p></div></div><form method="POST" action="backend/reschedule-booking.php" class="panel form-grid two"><?=csrfInput()?><input type="hidden" name="booking_id" value="<?=$id?>"><input type="hidden" id="serviceIds" value="<?=h($b['service_ids'])?>"><div class="field"><label>New Date</label><input id="bookingDate" name="booking_date" type="date" min="<?=date('Y-m-d')?>" max="<?=date('Y-m-d',strtotime('+'.$days.' days'))?>" value="<?=h($b['booking_date'])?>" required></div><div class="field"><label>New Time</label><select id="bookingTime" name="booking_time" required><option value="">Loading…</option></select></div><div class="span-2 button-row"><button class="btn primary">Save New Schedule</button><a class="btn ghost" href="admin-bookings.php">Cancel</a></div></form></main><script>const d=document.getElementById('bookingDate'),t=document.getElementById('bookingTime'),ids=document.getElementById('serviceIds').value;async function load(){const r=await fetch('backend/available-times.php?date='+encodeURIComponent(d.value)+'&service_ids='+encodeURIComponent(ids));const j=await r.json();t.innerHTML='<option value="">Select time</option>';if(j.status==='success')j.times.forEach(a=>{const o=new Option(a.label,a.value);o.disabled=!a.available;t.append(o)});}d.onchange=load;load();</script></body></html>
